#!/bin/bash
#
# build.sh — assemble and compile the FTAD report.
#
# Produces, in this directory:
#   master.md        the concatenated source (regenerated, not hand-edited)
#   FTAD_Report.tex  the LaTeX softcopy
#   FTAD_Report.pdf  the compiled report
#
# The .tex is generated by pandoc from master.md with preamble.tex injected,
# then compiled with XeLaTeX (required: fontspec needs a Unicode engine).
# Three passes are needed so the table of contents and the lastpage reference
# settle.

set -euo pipefail

cd "$(dirname "$0")"

python3 assemble.py

pandoc master.md \
    -o FTAD_Report.tex \
    --standalone \
    --top-level-division=chapter \
    --toc --toc-depth=2 \
    -V documentclass=report \
    -V fontsize=12pt \
    -V geometry:a4paper \
    -V geometry:margin=20mm \
    -H preamble.tex

python3 fix_tables.py

echo "FTAD_Report.tex written"

for pass in 1 2 3; do
    if xelatex -interaction=nonstopmode -halt-on-error FTAD_Report.tex \
            > "pass$pass.log" 2>&1
    then
        echo "xelatex pass $pass: ok"
    else
        echo "xelatex pass $pass: FAILED — see pass$pass.log"
        grep -m 20 -E '^!|^l\.[0-9]+' "pass$pass.log" || true
        exit 1
    fi
done

if [ -f FTAD_Report.pdf ]; then
    echo "pages: $(pdfinfo FTAD_Report.pdf | awk '/^Pages/{print $2}')"
fi
